/* Schritt 2 — local learning workspace, no analytics or external API calls. */
const EXT_KEY='schritt-v2';
let extra={version:2,words:[],learning:{},attempts:[],notes:'',weekly:null},extStorageOK=true;
try{const x=JSON.parse(localStorage.getItem(EXT_KEY));if(x&&x.version===2&&Array.isArray(x.words)&&x.learning&&Array.isArray(x.attempts))extra={...extra,...x};}catch{extStorageOK=false;}
function saveExtra(){try{localStorage.setItem(EXT_KEY,JSON.stringify(extra));extStorageOK=true;}catch{extStorageOK=false;showModal('<h3>لم يتم الحفظ</h3><p>مساحة المتصفح غير متاحة أو ممتلئة. صدّر نسخة احتياطية قبل إغلاق الصفحة.</p>');}}
const escapeHTML=esc;
function allWords(){return [...WORDS,...extra.words];}
function itemStat(id){return extra.learning[id]||{status:0,streak:0,ok:0,bad:0,next:0,last:0};}
function logExtra(id,ok,kind,typed='',self=false){const it={...itemStat(id)};it.streak=ok?it.streak+1:0;it.ok+=+ok;it.bad+=+!ok;it.status=ok?(it.streak>=4?3:1):2;it.last=Date.now();const days=ok?[1,3,7,14,30][Math.min(it.streak-1,4)]:0;it.next=Date.now()+days*86400000;extra.learning[id]=it;extra.attempts.unshift({id,ok,kind,typed,time:Date.now(),self});extra.attempts=extra.attempts.slice(0,4000);saveExtra();}
function dueExtra(){return Object.keys(extra.learning).filter(id=>itemStat(id).next<=Date.now());}
function statusSelect(id){return `<select class="status-select" data-ex-status="${esc(id)}" aria-label="مرحلة الإتقان">${statusLabels.map((s,i)=>`<option value="${i}" ${itemStat(id).status===i?'selected':''}>${s}</option>`).join('')}</select>`;}
const oldRender=render,oldBind=bind,oldHome=home,oldProgress=progress,oldReview=review;
const EXTRA_VIEWS={dictionary:dictionary,verbs:verbLibrary,grammarBook:grammarBook,phonetics:phonetics,sources:sources,workshop:workshop};
navs.splice(2,0,['dictionary','قاموسي'],['verbs','تصريف الأفعال'],['grammarBook','دليل القواعد']);navs.push(['phonetics','مختبر النطق'],['sources','المراجع والكتاب']);
['dictionary','verbs','grammarBook','phonetics','sources'].forEach(k=>icons[k]=icons.paths);
render=function(){if(topic||quiz){oldRender();return;}if(EXTRA_VIEWS[view]){stopMedia();$('#nav').innerHTML=navs.map(([v,l])=>`<a href="#${v}" data-nav="${v}" class="${v===view?'active':''}"><svg viewBox="0 0 24 24">${icons[v]||icons.paths}</svg>${l}</a>`).join('');$('#page-name').textContent=navs.find(n=>n[0]===view)?.[1]||'ورشة التدريب';EXTRA_VIEWS[view]();bind();updateHeader();}else oldRender();};
bind=function(){oldBind();document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>wordDetail(b.dataset.word));document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>ruleDetail(b.dataset.rule));document.querySelectorAll('[data-ex-status]').forEach(b=>b.onchange=()=>{const it={...itemStat(b.dataset.exStatus)};it.status=+b.value;it.next=Date.now()+(it.status===3?14:it.status===1?1:0)*86400000;it.last=Date.now();extra.learning[b.dataset.exStatus]=it;saveExtra();});document.querySelectorAll('[data-word-practice]').forEach(b=>b.onclick=()=>startPractice('single',[allWords().find(w=>w.id===b.dataset.wordPractice)],'word'));document.querySelectorAll('[data-say-extra]').forEach(b=>b.onclick=()=>say(b.dataset.sayExtra));};
home=function(){oldHome();const box=document.createElement('section');box.className='new-hero';box.innerHTML=`<h2>من كلمة تعرفها… إلى كلام تستخدمه.</h2><p>${allWords().length} مدخلًا تعليميًا • ${WORDS.filter(w=>w.type==='فعل').length} فعلًا بأربع صيغ زمنية • ${GRAMMAR_ROWS.length} درس قواعد • أضف حصيلتك الخاصة</p><div class="actions"><button class="secondary" id="to-dict">افتح قاموسي ←</button><button class="secondary" id="quick-new">اختبار كلمات متنوع</button><button class="secondary" id="to-grammar">راجع قاعدة</button></div>`;$('#app').prepend(box);$('#to-dict').onclick=()=>go('dictionary');$('#quick-new').onclick=()=>startPractice('level');$('#to-grammar').onclick=()=>go('grammarBook');};
function viewHead(title,desc){return `<div class="view-head"><span class="eyebrow">خطوة ٢ / مساحة أوسع للتعلّم</span><h1>${title}</h1><p>${desc}</p></div>`;}
let dictFilters={q:'',level:'all',type:'all',status:'all',page:0};
function searchNorm(s){return String(s||'').toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').trim();}
function wordMatches(w,f){const q=searchNorm(f.q),hay=searchNorm([w.de,w.ar,w.en,w.plural,w.sentence,...(w.forms||[])].join(' '));return (!q||hay.includes(q))&&(f.level==='all'||w.level===f.level)&&(f.type==='all'||w.type===f.type)&&(f.status==='all'||(f.status==='due'?itemStat(w.id).last&&itemStat(w.id).next<=Date.now():itemStat(w.id).status===+f.status));}
function dictionary(){const verbsOnly=view==='verbs';if(verbsOnly)dictFilters.type='فعل';$('#app').innerHTML=viewHead(verbsOnly?'الفعل… بكل ضمايره':'قاموسك الذي يكبر معك',verbsOnly?'المضارع، الماضي البسيط، Perfekt، وFutur I؛ مع مثال وسؤال وملاحظات الاستخدام.':'ابحث بالألماني أو الإنجليزي أو العربي. اقرأ المعنى، كوّن جملة، ثم اسأل ورد.')+`<div class="toolbar"><input id="dict-search" class="searchwide" type="search" placeholder="مثلًا: work / يعمل / arbeiten" aria-label="بحث في القاموس" value="${esc(dictFilters.q)}"><select id="dict-level" aria-label="مستوى الكلمات"><option value="all">كل المستويات</option>${['A1','A2','B1','B2'].map(l=>`<option ${l===dictFilters.level?'selected':''}>${l}</option>`).join('')}</select>${verbsOnly?'':`<select id="dict-type" aria-label="نوع الكلمة"><option value="all">كل الأنواع</option>${[...new Set(allWords().map(w=>w.type))].map(t=>`<option ${t===dictFilters.type?'selected':''}>${esc(t)}</option>`).join('')}</select>`}<select id="dict-status" aria-label="مرحلة الكلمة"><option value="all">كل المراحل</option><option value="due" ${dictFilters.status==='due'?'selected':''}>مستحق للمراجعة</option>${statusLabels.map((s,i)=>`<option value="${i}" ${dictFilters.status===String(i)?'selected':''}>${s}</option>`).join('')}</select></div><div class="toolbar"><button class="primary" id="new-word">＋ أضف كلمة</button><button class="secondary" id="practice-filter">درّبني على هذه النتائج</button><button class="secondary" id="import-words">استيراد كلمات</button><button class="secondary" id="export-words">تصدير القاموس</button></div><div class="notice">القائمة التعليمية الحالية ${WORDS.length} مدخلًا من إعداد خطوة، وليست نسخة كاملة من dict.cc أو قائمة رسمية للمستويات. ابحث خارجيًا من بطاقة الكلمة، وأضف المعنى المناسب لسياقك. المستويات تقديرية للتدريب.</div><div id="dict-count" class="count-line"></div><div id="dict-results" class="dictionary-grid"></div><div id="dict-pages" class="pager"></div>`;
const fill=()=>{const list=allWords().filter(w=>wordMatches(w,dictFilters)),start=dictFilters.page*18;$('#dict-count').innerHTML=`<span>${list.length} نتيجة / ${allWords().length} مدخل</span><span>جديد ← قيد التدريب ← متقن؛ والخطأ يعيد للمراجعة</span>`;$('#dict-results').innerHTML=list.slice(start,start+18).map(w=>`<article class="panel"><div class="tagrow"><span class="badge">${w.level}</span><span class="badge">${esc(w.type)}</span><span class="status-pill">${statusLabels[itemStat(w.id).status]}</span></div><h3 class="de" lang="de">${esc(w.de)}</h3><p>${esc(w.ar)}</p><p class="de subtle">${esc(w.en)}</p><p class="de subtle">${esc(w.sentence)}</p><div class="actions"><button class="secondary" data-word="${w.id}">${w.type==='فعل'?'المعنى والتصريف':'المعنى والجملة'} ←</button><button class="text-link" data-word-practice="${w.id}">تدرّب</button></div></article>`).join('')||'<div class="panel empty">لا توجد نتائج. جرّب كلمة أخرى أو أضف الكلمة لقاموسك.</div>';$('#dict-pages').innerHTML=`<button class="secondary" id="prev-page" ${dictFilters.page===0?'disabled':''}>السابق</button><span>${dictFilters.page+1} / ${Math.max(1,Math.ceil(list.length/18))}</span><button class="secondary" id="next-page" ${start+18>=list.length?'disabled':''}>التالي</button>`;$('#prev-page').onclick=()=>{dictFilters.page--;fill();};$('#next-page').onclick=()=>{dictFilters.page++;fill();};bind();};
$('#dict-search').oninput=e=>{dictFilters.q=e.target.value;dictFilters.page=0;fill();};['level','type','status'].forEach(k=>{const e=$('#dict-'+k);if(e)e.onchange=()=>{dictFilters[k]=e.value;dictFilters.page=0;fill();};});$('#new-word').onclick=addWord;$('#practice-filter').onclick=()=>startPractice('filtered',allWords().filter(w=>wordMatches(w,dictFilters)));$('#import-words').onclick=importWords;$('#export-words').onclick=()=>downloadJSON({schema:'schritt-words-v1',words:allWords()},'schritt-dictionary.json');fill();}
function verbLibrary(){dictionary();}
function modalWide(html){showModal(html);$('#modal .panel').classList.add('wide-modal');bind();}
function wordDetail(id){const w=allWords().find(x=>x.id===id);if(!w)return;modalWide(`<div id="word-detail"><span class="badge">${w.level} • ${esc(w.type)}</span><h2 class="de study-word" lang="de">${esc(w.de)}</h2><p>${esc(w.ar)} <span class="de subtle">/ ${esc(w.en)}</span></p>${w.plural?`<p>الجمع: <b class="inline-de">${esc(w.plural)}</b>${w.plural==='—'?' — لا جمع شائع في هذا المعنى':''}</p>`:''}<div class="notice"><b>الكلمة في جملة</b><p class="de" lang="de">${esc(w.sentence)}</p><b>حوّلها لسؤال</b><p class="de" lang="de">${esc(w.question)}</p></div><div class="actions"><button class="secondary" data-say-extra="${esc(w.sentence)}">اسمع الجملة</button><button class="secondary" data-say-extra="${esc(w.question)}">اسمع السؤال</button><button class="primary" data-word-practice="${w.id}">ابدأ التدريب</button></div>${w.forms?`<div class="morph" id="tense-tabs">${['Präsens','Präteritum','Perfekt','Futur I'].map(t=>`<button data-tense="${t}">${t}</button>`).join('')}</div><div id="verb-table"></div><p class="word-notes">المصدر: <b class="inline-de">${esc(w.de)}</b> • Partizip II: <b class="inline-de">${esc(w.participle)}</b> • المساعد: <b class="inline-de">${esc(w.aux)}</b></p><p class="notice amber">Perfekt وFutur I في الجدول يوضحان طرفَي التركيب. المفعول والظرف يأتيان بينهما عند بناء الجملة. مع Modalverb وفعل ثانٍ في Perfekt تُستعمل صيغة بديلة مثل <span class="inline-de">Ich habe arbeiten müssen.</span></p>`:''}<p class="word-notes">${esc(w.note||'احفظ الاسم مع أداته وجمعه، واستخدمه في جملة تخصك. الصفة قبل الاسم قد تتغير نهايتها.')}</p><div class="toolbar">${statusSelect(w.id)}</div><div class="actions"><a class="secondary" target="_blank" rel="noopener" href="https://www.dict.cc/?s=${encodeURIComponent(w.de.replace(/^(der|die|das) /,''))}">ابحث في dict.cc ↗</a><a class="secondary" target="_blank" rel="noopener" href="https://www.arabdict.com/ar/deutsch-arabisch/${encodeURIComponent(w.de.replace(/^(der|die|das) /,''))}">Arabdict ↗</a></div><p class="source-evidence">${esc(w.source||'مدخل شخصي')} — الروابط تفتح خارج المدرب عند الضغط؛ لا يتم جلب ترجمة أو إرسال تسجيلات تلقائيًا.</p></div>`);
if(w.forms){const show=t=>{$('#verb-table').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>الضمير</th><th>${t}</th><th>اسمع</th></tr></thead><tbody>${verbForms(w,t).map((f,i)=>`<tr><td class="de detail-pronoun">${PRONOUNS[i]}</td><td class="de">${esc(f)}</td><td><button class="text-link" data-say-extra="${esc(PRONOUNS[i].split(' / ')[0]+' '+f)}">اسمع</button></td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-tense]').forEach(e=>e.classList.toggle('active',e.dataset.tense===t));bind();};document.querySelectorAll('[data-tense]').forEach(b=>b.onclick=()=>show(b.dataset.tense));show('Präsens');}}
function addWord(){modalWide(`<h2>كلمة جديدة… من حياتك</h2><form id="word-form" class="form-grid"><label>الكلمة بالألماني، والأداة للاسم<input name="de" dir="ltr" required maxlength="100" placeholder="der Schlüssel"></label><label>المعنى بالعربي<input name="ar" required maxlength="150"></label><label>المعنى بالإنجليزي<input name="en" dir="ltr" maxlength="150"></label><label>الجمع<input name="plural" dir="ltr" maxlength="100"></label><label>المستوى<select name="level"><option>A1</option><option>A2</option><option>B1</option><option>B2</option></select></label><label>النوع<select name="type"><option>اسم</option><option>فعل</option><option>صفة</option><option>تعبير</option><option>ظرف</option></select></label><label class="full">جملة بالألماني<input name="sentence" dir="ltr" required maxlength="500"></label><label class="full">سؤال بالألماني<input name="question" dir="ltr" required maxlength="500"></label><label class="full">المصدر أو ملاحظة<input name="note" maxlength="500" placeholder="مثلًا: كلمتي من درس اليوم"></label><p class="subtle full">لإضافة تصريفات فعل مخصص، استخدم الاستيراد بصيغة JSON من نموذج تصدير القاموس. لن يخمّن المدرب تصريفًا غير معروف.</p><button class="primary" type="submit">أضف لقاموسي</button></form>`);$('#word-form').onsubmit=e=>{e.preventDefault();const w=Object.fromEntries(new FormData(e.target));if(!w.de.trim()||!w.ar.trim()||!w.sentence.trim()||!w.question.trim())return;w.id='u-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);w.source='مدخل شخصي';extra.words.push(w);saveExtra();$('#modal').hidden=true;dictFilters={q:w.de,level:'all',type:'all',status:'all',page:0};go('dictionary');};}
function downloadJSON(obj,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safeWord(raw,index){if(!raw||typeof raw!=='object')throw Error('مدخل غير صالح');const w={};for(const k of ['de','ar','en','sentence','question','note','plural','source','past','pastClass','participle','aux']){if(raw[k]!=null){if(typeof raw[k]!=='string'||raw[k].length>1000)throw Error('نص طويل أو نوع غير صحيح');w[k]=raw[k].trim();}}if(!w.de||!w.ar||!w.sentence||!w.question)throw Error('كل كلمة تحتاج de وar وsentence وquestion');w.type=['اسم','فعل','صفة','ظرف','لون','رابط','تعبير'].includes(raw.type)?raw.type:'تعبير';w.level=['A1','A2','B1','B2'].includes(raw.level)?raw.level:'A1';w.id='u-'+Date.now()+'-'+index+'-'+Math.random().toString(36).slice(2,6);if(raw.forms){if(!Array.isArray(raw.forms)||raw.forms.length!==6||!raw.forms.every(f=>typeof f==='string'&&f.length<100)||!w.past||!['s','w'].includes(w.pastClass)||!w.participle||!['sein','haben'].includes(w.aux))throw Error('تصريف الفعل يحتاج ٦ صيغ وبيانات ماضٍ صحيحة');w.forms=raw.forms;}return w;}
function parseWordFile(text,name){if(/\.json$/i.test(name)){const data=JSON.parse(text);return Array.isArray(data)?data:data.words;}const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);const delim=name.endsWith('.tsv')?'\t':',';function cells(line){let a=[],s='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){s+='"';i++;}else quote=!quote;}else if(c===delim&&!quote){a.push(s);s='';}else s+=c;}if(quote)throw Error('اقتباس غير مغلق؛ استخدم JSON للنص متعدد الأسطر');a.push(s);return a;}const head=cells(lines.shift());return lines.filter(Boolean).map(line=>Object.fromEntries(cells(line).map((v,i)=>[head[i]?.trim(),v])));}
function importWords(){modalWide('<h2>استورد حصيلة الكلمات</h2><p>JSON أو CSV أو TSV بترميز UTF-8. الأعمدة المطلوبة: <span class="inline-de">de, ar, sentence, question</span>؛ اختياري: <span class="inline-de">en, plural, level, type, note</span>.</p><p class="subtle">حتى ١٠ آلاف مدخل في المرة؛ حد الملف ١٠ ميجابايت. التكرارات المتطابقة في الكلمة والمعنى لن تضاف. صدّر القاموس لرؤية نموذج بيانات تصريف الأفعال.</p><input id="word-file" type="file" accept=".json,.csv,.tsv"><div id="import-feedback" aria-live="polite"></div>');$('#word-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('الملف أكبر من ١٠ ميجابايت');const rows=parseWordFile(await f.text(),f.name);if(!Array.isArray(rows)||rows.length>10000||!rows.length)throw Error('قائمة غير صالحة أو العدد خارج الحدود');const valid=rows.map(safeWord),seen=new Set(allWords().map(w=>searchNorm(w.de)+'|'+searchNorm(w.ar)));const unique=valid.filter(w=>{const k=searchNorm(w.de)+'|'+searchNorm(w.ar);if(seen.has(k))return false;seen.add(k);return true;});$('#import-feedback').innerHTML=`<div class="notice">${unique.length} كلمة جديدة، و${rows.length-unique.length} تكرارًا. سيتم الاحتفاظ بكلماتك الحالية.</div><button id="confirm-words" class="primary">أضف الكلمات</button>`;$('#confirm-words').onclick=()=>{extra.words.push(...unique);saveExtra();$('#modal').hidden=true;go('dictionary');};}catch(err){$('#import-feedback').textContent='تعذر الاستيراد: '+err.message;}};}

let ruleFilters={level:'all',q:''};
function grammarBook(){$('#app').innerHTML=viewHead('افهم القاعدة… ثم استخدمها','دليل متدرّج لأساسيات A1–B2. شرح عربي وأمثلة واختبار لكل موضوع؛ التفاصيل والاستثناءات في المراجع الأصلية.')+`<div class="toolbar"><input class="searchwide" id="rule-search" type="search" placeholder="ابحث عن Dativ أو الماضي أو النفي" value="${esc(ruleFilters.q)}"><select id="rule-level"><option value="all">كل المستويات</option>${['A1','A2','B1','B2'].map(l=>`<option ${l===ruleFilters.level?'selected':''}>${l}</option>`).join('')}</select><button class="primary" id="grammar-exam">اختبار قواعد متنوع</button></div><div class="notice">${GRAMMAR_ROWS.length} موضوعًا مركزيًا. لا توجد نسخة مختصرة تشرح كل قواعد اللغة واستثناءاتها؛ هذه خريطة تدريب تتوسع بالممارسة.</div><div id="rule-results" class="lesson-grid"></div>`;const fill=()=>{const list=GRAMMAR_ROWS.filter(r=>(ruleFilters.level==='all'||r.level===ruleFilters.level)&&searchNorm(r.title+' '+r.explain+' '+r.id).includes(searchNorm(ruleFilters.q)));$('#rule-results').innerHTML=list.map(r=>`<article class="panel grammar-card"><span class="badge">${r.level} • ${statusLabels[itemStat(r.id).status]}</span><h3>${r.title}</h3><p class="subtle">${esc(r.explain.slice(0,105))}…</p><p class="de">${esc(r.example)}</p><button class="secondary" data-rule="${r.id}">افهم وتدرّب ←</button></article>`).join('')||'<div class="panel empty">لا توجد نتائج.</div>';bind();};$('#rule-search').oninput=e=>{ruleFilters.q=e.target.value;fill();};$('#rule-level').onchange=e=>{ruleFilters.level=e.target.value;fill();};$('#grammar-exam').onclick=()=>startPractice('grammar',GRAMMAR_ROWS.filter(r=>ruleFilters.level==='all'||r.level===ruleFilters.level),'grammar');fill();}
function ruleDetail(id){const r=GRAMMAR_ROWS.find(x=>x.id===id);modalWide(`<span class="badge">${r.level}</span><h2>${r.title}</h2><p class="word-notes">${esc(r.explain)}</p><div class="prompt de">${esc(r.example)}</div><div class="notice amber">${esc(r.pitfall)}</div>${r.id==='g-cases'||r.id==='g-dative'?`<div class="table-wrap"><table class="data-table case-table"><tr><th>Kasus</th><th>Maskulin</th><th>Neutrum</th><th>Feminin</th><th>Plural</th></tr><tr><td>Nominativ</td><td>der</td><td>das</td><td>die</td><td>die</td></tr><tr><td>Akkusativ</td><td>den</td><td>das</td><td>die</td><td>die</td></tr><tr><td>Dativ</td><td>dem</td><td>dem</td><td>der</td><td>den (+n غالبًا)</td></tr><tr><td>Genitiv</td><td>des (+s/es)</td><td>des (+s/es)</td><td>der</td><td>der</td></tr></table></div>`:''}<div class="actions"><button class="primary" id="practice-rule">اختبر فهمي</button><button class="secondary" data-say-extra="${esc(r.example)}">اسمع المثال</button></div>${statusSelect(r.id)}`);$('#practice-rule').onclick=()=>startPractice('single',[r],'grammar');}

let exercise2=null;
function startPractice(kind,pool=null,type='word'){stopMedia();$('#modal').hidden=true;topic=null;quiz=null;if(!pool){pool=allWords();if(kind==='level')pool=pool.filter(w=>w.level===state.level);if(kind==='due')pool=pool.filter(w=>dueExtra().includes(w.id));if(kind==='weak')pool=pool.filter(w=>itemStat(w.id).status===2);if(kind==='weekly')pool=pool.filter(w=>itemStat(w.id).last);}if(!pool.length){showModal('<h3>لا توجد عناصر لهذا التدريب</h3><p>ابدأ بكلمات جديدة أو غيّر الفلتر.</p>');return;}exercise2={kind,type,list:shuffle(pool).slice(0,kind==='single'?1:kind==='lesson'?pool.length:10),index:0,score:0,answered:false,log:[],mode:'mcq'};view='workshop';render();}
function workshop(){const x=exercise2;if(!x){go('dictionary');return;}if(x.index>=x.list.length){if(x.kind==='weekly'){extra.weekly=Date.now();saveExtra();}$('#app').innerHTML=viewHead('حصيلة الجلسة','الدرجات هنا للتدريب، وليست تقديرًا رسميًا لمستواك.')+`<div class="exercise"><div class="panel"><div class="score">${x.score}<span style="font-size:24px"> / ${x.list.length}</span></div>${x.log.map(l=>`<div class="record"><span>${l.ok?'✓':'↻'}</span><div><b>${esc(l.title)}</b><p class="de subtle">${esc(l.answer)}</p></div></div>`).join('')}<div class="actions"><button class="primary" id="repeat-new">أعد التدريب بترتيب جديد</button><button class="secondary" id="done-study">اذهب للمراجعة</button></div></div></div>`;$('#repeat-new').onclick=()=>startPractice(x.kind,x.list,x.type);$('#done-study').onclick=()=>go('review');return;}
const w=x.list[x.index],isRule=x.type==='grammar';$('#app').innerHTML=`<div class="exercise"><div class="panel"><div class="section-title"><span class="badge">${w.level} • ${isRule?'قواعد':esc(w.type)}</span><span>${x.index+1} / ${x.list.length}</span></div><div class="progress-line"><span style="width:${x.index/x.list.length*100}%"></span></div>${!isRule?`<div class="morph"><button data-practice-mode="mcq" class="${x.mode==='mcq'?'active':''}">معنى</button><button data-practice-mode="spell" class="${x.mode==='spell'?'active':''}">استرجاع الكلمة</button><button data-practice-mode="sentence" class="${x.mode==='sentence'?'active':''}">كلمة ← جملة</button><button data-practice-mode="question" class="${x.mode==='question'?'active':''}">جملة ← سؤال</button>${w.forms?'<button data-practice-mode="verb">تصريف</button>':''}</div>`:''}<div id="task2"></div><div id="feedback2" aria-live="polite"></div><div id="actions2" class="actions"></div></div></div>`;
document.querySelectorAll('[data-practice-mode]').forEach(b=>b.onclick=()=>{x.mode=b.dataset.practiceMode;workshop();});x.answered=false;let answer,prompt,options;
if(isRule){prompt=w.prompt;answer=w.answer;options=shuffle(w.options);}
else if(x.mode==='mcq'){prompt=w.de;answer=w.ar;const alt=shuffle(allWords().filter(a=>a.id!==w.id&&a.ar!==answer&&a.type===w.type)).map(a=>a.ar);options=shuffle([answer,...[...new Set(alt)].slice(0,3)]);}
else if(x.mode==='spell'){prompt=w.ar+' / '+w.en;answer=w.de;}
else if(x.mode==='sentence'){prompt=w.de;answer=w.sentence;}
else if(x.mode==='question'){prompt=w.sentence;answer=w.question;}
else {const index=Math.floor(Math.random()*6);prompt=w.de+' → '+PRONOUNS[index]+' (Präsens)';answer=w.forms[index];}
$('#task2').innerHTML=`<h2>${isRule?w.title:({mcq:'اختر المعنى المناسب',spell:'اكتب الكلمة بالألماني؛ للاسم اكتب الأداة أيضًا',sentence:'اكتب الجملة المرجعية من ذاكرتك',question:'اكتب السؤال المرجعي المناسب للجملة',verb:'صرّف الفعل مع الضمير'}[x.mode])}</h2><div class="prompt ${x.mode==='spell'?'':'de'}" lang="de">${esc(prompt)}</div>${options?`<div class="options">${options.map(o=>`<button class="option" data-opt2="${esc(o)}" ${!isRule?'style="direction:rtl;text-align:right"':''}>${esc(o)}</button>`).join('')}</div>`:`<input id="typed2" class="big-input de" lang="de" autocomplete="off" placeholder="Deine Antwort …"><div class="actions"><button class="primary" id="check2">راجع إجابتي</button><button class="secondary" id="hint2">أظهر النموذج للمذاكرة</button></div>${['sentence','question'].includes(x.mode)?'<p class="writing-note">مطابقة مرجعية، وليست تصحيحًا لغويًا عامًا. قد تكون إجابة مختلفة صحيحة؛ استخدم التقييم الذاتي بعد المقارنة.</p>':''}`}`;
const finish=(ok,typed,self=false)=>{if(x.answered)return;x.answered=true;if(ok)x.score++;logExtra(w.id,ok,isRule?'قواعد':x.mode,typed,self);x.log.push({title:isRule?w.title:w.de,ok,answer});$('#feedback2').innerHTML=`<div class="feedback ${ok?'':'bad'}"><b>${ok?'إجابة مطابقة ✓':self?'سُجّلت للمراجعة':!isRule&&['sentence','question'].includes(x.mode)?'لم تطابق النموذج؛ قارن المعنى والتركيب':'راجع الإجابة الصحيحة'}</b><div class="de">${esc(answer)}</div><p>${esc(isRule?w.why:w.note||'كرر المثال ثم غيّر معلومة واحدة لتستخدمه في حياتك.')}</p>${!isRule?`<div class="de">${esc(w.sentence)}<br>${esc(w.question)}</div>`:''}${self?'<small>تقييم ذاتي مسجل بوضوح في السجل.</small>':''}</div>`;$('#actions2').innerHTML='<button class="primary" id="next2">التالي ←</button>';$('#next2').onclick=()=>{x.index++;x.mode='mcq';render();};document.querySelectorAll('[data-opt2]').forEach(b=>{b.disabled=true;if(b.dataset.opt2===answer)b.classList.add('correct');else if(b.dataset.opt2===typed)b.classList.add('wrong');});if($('#check2'))$('#check2').disabled=true;if($('#hint2'))$('#hint2').disabled=true;document.querySelectorAll('[data-practice-mode]').forEach(b=>b.disabled=true);};
document.querySelectorAll('[data-opt2]').forEach(b=>b.onclick=()=>finish(b.dataset.opt2===answer,b.dataset.opt2));if(!options){$('#check2').onclick=()=>{const val=$('#typed2').value;if(!val.trim()){ $('#feedback2').textContent='اكتب إجابة أولًا.';return;}if(norm(val)===norm(answer)){finish(true,val);return;}$('#feedback2').innerHTML=`<div class="feedback bad"><b>لم تطابق الإجابة المرجعية</b><p class="de">${esc(answer)}</p><p>${['sentence','question'].includes(x.mode)?'ممكن تكون إجابتك مختلفة وصحيحة. قارنها بالنموذج؛ المدرب هنا لا يحكم على أي جملة حرة.':'راجع الحروف والأداة والتصريف، ثم أعد التدريب.'}</p></div>`;$('#actions2').innerHTML=`<button class="secondary" id="mark-review2">احتاج مراجعة</button>${['sentence','question'].includes(x.mode)?'<button class="primary" id="mark-good2">إجابتي بديل صحيح — تقييم ذاتي</button>':''}`;$('#mark-review2').onclick=()=>finish(false,val,true);if($('#mark-good2'))$('#mark-good2').onclick=()=>finish(true,val,true);};$('#typed2').onkeydown=e=>{if(e.key==='Enter'&&!x.answered)$('#check2').click();};$('#hint2').onclick=()=>{$('#feedback2').innerHTML=`<div class="notice"><div class="de">${esc(answer)}</div><p>اقرأ النموذج بصوتك ثم أعده من الذاكرة في المرة القادمة.</p></div>`;$('#actions2').innerHTML='<button class="secondary" id="after-hint">سجّلها للمراجعة وانتقل</button>';$('#after-hint').onclick=()=>finish(false,'عرض النموذج',true);$('#check2').disabled=true;};}}

review=function(){oldReview();const cards=document.createElement('div');cards.className='panel';cards.style.marginBottom='20px';const dueIds=dueExtra(),weak=allWords().filter(w=>itemStat(w.id).status===2);cards.innerHTML=`<h3>مراجعة القاموس والقواعد</h3><p class="subtle">${dueIds.length} عنصرًا مستحقًا • ${weak.length} كلمة ضعيفة. المراجعات بعد نجاح متتالٍ: ١، ٣، ٧، ١٤، ثم ٣٠ يومًا. الخطأ يعيد سلسلة النجاح إلى الصفر.</p><div class="actions"><button class="primary" id="review-words2">الكلمات المستحقة</button><button class="secondary" id="review-weak2">الكلمات الضعيفة</button><button class="secondary" id="review-rules2">القواعد المستحقة</button><button class="secondary" id="weekly2">مراجعة أسبوعية للكلمات</button></div><p class="subtle">آخر مراجعة أسبوعية للقاموس: ${extra.weekly?new Date(extra.weekly).toLocaleDateString('ar-EG'):'لم تُجرَ بعد'}</p><div class="tagrow">${allWords().filter(w=>dueIds.includes(w.id)).slice(0,10).map(w=>`<button class="secondary" data-word="${w.id}">${esc(w.de)}</button>`).join('')}</div>`;$('#app').prepend(cards);$('#review-words2').onclick=()=>startPractice('due');$('#review-weak2').onclick=()=>startPractice('weak');$('#review-rules2').onclick=()=>startPractice('due',GRAMMAR_ROWS.filter(r=>dueIds.includes(r.id)),'grammar');$('#weekly2').onclick=()=>startPractice('weekly');};
progress=function(){oldProgress();const panel=document.createElement('section');panel.className='panel';panel.style.marginBottom='20px';panel.innerHTML=`<h3>حصيلتك الجديدة في القاموس والقواعد</h3><div class="stats">${statusLabels.map((s,i)=>`<div class="stat"><div><small>${s}</small><strong>${[...allWords(),...GRAMMAR_ROWS].filter(w=>itemStat(w.id).status===i).length}</strong></div></div>`).join('')}</div><p class="subtle">${extra.words.length} مدخلًا شخصيًا • ${extra.attempts.length} محاولة مسجلة. الإتقان هنا بعد ٤ نجاحات متتالية؛ ليس إثباتًا لإتقان مستوى لغوي.</p><div class="toolbar"><button id="backup-all2" class="primary">صدّر نسخة كاملة للتقدّم والكلمات</button><button id="restore-all2" class="secondary">استرجع نسخة كاملة</button></div><h3>آخر أخطاء القاموس والقواعد</h3>${extra.attempts.filter(a=>!a.ok).slice(0,12).map(a=>{const w=allWords().find(w=>w.id===a.id)||GRAMMAR_ROWS.find(w=>w.id===a.id);return `<div class="record"><div><b>${esc(w?.de||w?.title||'مدخل محذوف')}</b><p class="de subtle">${esc(a.typed)}</p><small>${esc(a.kind)}${a.self?' • تقييم ذاتي':''} • ${new Date(a.time).toLocaleDateString('ar-EG')}</small></div><button class="secondary" ${w?.de?'data-word':'data-rule'}="${a.id}">راجع</button></div>`;}).join('')||'<p class="subtle">لم تسجّل أخطاء بعد.</p>'}`;$('#app').prepend(panel);$('#backup-all2').onclick=()=>downloadJSON({schema:'schritt-backup-v2',base:state,extra},'schritt-complete-backup.json');$('#restore-all2').onclick=restoreBackup;};
function validateBackup(v){if(v?.schema!=='schritt-backup-v2'||!v.base||!v.extra||v.extra.version!==2)throw Error('نسخة غير متوافقة');const b=v.base,x=v.extra;if(!['A1','A2','B1','B2'].includes(b.level)||!Array.isArray(b.records)||!Array.isArray(b.visits)||!b.items||typeof b.items!=='object'||!Array.isArray(x.words)||!Array.isArray(x.attempts)||!x.learning||typeof x.learning!=='object'||x.words.length>20000||x.attempts.length>4000||b.records.length>1200||typeof x.notes!=='string')throw Error('بنية غير صالحة');const ids=new Set(TOPICS.map(t=>t.id));if(b.records.some(r=>!ids.has(r.id)||typeof r.correct!=='boolean'||!Number.isFinite(r.time)||typeof r.kind!=='string')||Object.entries(b.items).some(([id,it])=>!ids.has(id)||![0,1,2,3].includes(it.status)||!Number.isFinite(it.ok)||!Number.isFinite(it.bad)))throw Error('سجل الدروس غير صالح');const custom=x.words.map((w,i)=>{const out=safeWord(w,i);if(typeof w.id!=='string'||!/^u-[\w-]+$/.test(w.id))throw Error('معرف كلمة غير صالح');out.id=w.id;return out;});const allIds=new Set([...WORDS,...custom,...GRAMMAR_ROWS].map(w=>w.id));if(allIds.size!==WORDS.length+custom.length+GRAMMAR_ROWS.length)throw Error('معرفات مكررة');const learning={};for(const [id,it] of Object.entries(x.learning)){if(!allIds.has(id)||![0,1,2,3].includes(it.status)||!['streak','ok','bad','next','last'].every(k=>Number.isFinite(it[k])&&it[k]>=0))throw Error('مراجعة غير صالحة');learning[id]={status:it.status,streak:it.streak,ok:it.ok,bad:it.bad,next:it.next,last:it.last};}if(x.attempts.some(a=>!allIds.has(a.id)||typeof a.ok!=='boolean'||typeof a.kind!=='string'||typeof a.typed!=='string'||!Number.isFinite(a.time)))throw Error('محاولة غير صالحة');return {base:{level:b.level,records:b.records,visits:b.visits.filter(v=>typeof v==='string'),items:b.items,lastWeekly:b.lastWeekly||null},extra:{version:2,words:custom,learning,attempts:x.attempts,notes:x.notes.slice(0,100000),weekly:Number.isFinite(x.weekly)?x.weekly:null}};}
function restoreBackup(){modalWide('<h2>استرجاع النسخة الكاملة</h2><p>الاسترجاع يستبدل تقدّمك وكلماتك الحاليين. صدّر نسخة منهما أولًا إن احتجت الاحتفاظ بهما.</p><input id="backup-file2" type="file" accept=".json"><div id="backup-feedback2"></div>');$('#backup-file2').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error('الملف كبير');const v=validateBackup(JSON.parse(await f.text()));$('#backup-feedback2').innerHTML=`<div class="notice">نسخة سليمة: ${v.extra.words.length} كلمة شخصية، ${v.extra.attempts.length} محاولة.</div><button id="confirm-restore2" class="primary">استبدل البيانات الحالية بهذه النسخة</button>`;$('#confirm-restore2').onclick=()=>{state=v.base;extra=v.extra;save();saveExtra();$('#modal').hidden=true;go('progress');};}catch(err){$('#backup-feedback2').textContent='تعذر الاسترجاع: '+err.message;}};}

function phonetics(){$('#app').innerHTML=viewHead('مختبر النطق','اسمع، لاحظ موضع الفم، كرر، ثم سجّل إجابتك في مسار المحادثة. المقارنة ذاتية؛ لا توجد درجة نطق آلية.')+`<div class="notice">الصوت يستخدم صوتًا ألمانيًا محليًا من جهازك إن توفّر. التسجيل يعمل بإذن الميكروفون على localhost أو HTTPS في المتصفحات الداعمة، ويُحذف عند الخروج من التمرين. لا نرسل صوتك للخارج.</div><div class="toolbar"><button class="primary" id="check-audio2">افحص الصوت والميكروفون</button><button class="secondary" id="speak-route2">افتح تدريبات المحادثة</button></div><div class="lesson-grid">${PHONETICS.map((p,i)=>`<article class="panel"><span class="badge">تدريب ${i+1}</span><h3 class="de">${p[0]}</h3><p class="de">${p[1]}</p><p class="word-notes">${p[2]}</p><p class="de">${p[3]}</p><button class="secondary" data-say-extra="${esc(p[3])}">اسمع وكرر</button></article>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>دفتر جملك</h3><p class="subtle">اكتب ٣ جمل تخصك بعد كل درس. دفتر محفوظ، بدون تصحيح آلي للنص الحر.</p><textarea id="sentence-notebook2" class="note-editor" placeholder="Heute habe ich …">${esc(extra.notes)}</textarea><span id="note-saved2" class="subtle"></span></div>`;$('#check-audio2').onclick=audioCheck;$('#speak-route2').onclick=()=>go('speak');$('#sentence-notebook2').oninput=e=>{extra.notes=e.target.value.slice(0,100000);saveExtra();$('#note-saved2').textContent=extStorageOK?'تم الحفظ':'لم يُحفظ';};}
function audioCheck(){const voices='speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>v.lang.startsWith('de')&&v.localService):[];modalWide(`<h2>حالة أدوات التدريب</h2><table class="data-table"><tr><td>تشغيل الصفحة</td><td>${location.protocol==='file:'?'ملف مباشر':location.hostname==='localhost'||location.hostname==='127.0.0.1'?'Local Server':'موقع مستضاف'}</td></tr><tr><td>سياق آمن للميكروفون</td><td>${window.isSecureContext?'متاح':'غير متاح؛ استخدم localhost أو HTTPS'}</td></tr><tr><td>دعم التسجيل</td><td>${navigator.mediaDevices?.getUserMedia&&window.MediaRecorder?'مدعوم؛ يحتاج إذنك عند الضغط على سجّل':'غير متاح في هذا المتصفح أو السياق'}</td></tr><tr><td>أصوات ألمانية محلية</td><td>${voices.length?voices.map(v=>esc(v.name)).join('، '):'لم يظهر صوت؛ ثبّت صوتًا ألمانيًا من إعدادات نظامك، وانتظر تحميله ثم افحص مرة أخرى'}</td></tr><tr><td>حفظ المتصفح</td><td>${storageOK&&extStorageOK?'متاح بحسب آخر محاولة حفظ':'تعذر بعض الحفظ؛ صدّر بياناتك'}</td></tr></table><p class="subtle">توفر واجهة الميكروفون لا يثبت أن الإذن مُنح؛ التسجيل الحقيقي يُختبر داخل التمرين بعد ضغطك على زر التسجيل.</p>`);}
function sources(){$('#app').innerHTML=viewHead('كتابك… ومصادر تثق بها','خطة استخدام متكاملة: درس من المرجع، ثم إنتاج جمل وأسئلة من حياتك، ثم مراجعة متباعدة.')+`<div class="panel"><h3>المراجع التي وجدتها ضمن ملفاتك</h3><p class="word-notes">Netzwerk Neu A1 — Kursbuch وÜbungsbuch؛ وملف PHONETIK؛ وملف nominativ-akk-dativ. أجزاء من الكتب والنطق صور ممسوحة، لذلك لم تُستخرج نصوصها بالكامل. الربط هنا على مستوى الموضوع، وليس مطابقة مزعومة لكل صفحة.</p><p class="notice amber">تصحيح من مذكرة الحالات: عدد الأشخاص لا يحدد الحالة الإعرابية. الفعل وحرف الجر ووظيفة الاسم يحددونها. مثال: <span class="inline-de">Ich helfe dem Mann.</span> فيه Dativ دون Akkusativ.</p><div class="table-wrap"><table class="data-table"><tr><th>تذاكر في المرجع</th><th>تعمل هنا بعده</th><th>الناتج اليومي</th></tr><tr><td>تعارف وأسرة وأصدقاء</td><td>قاموس + سؤال وجواب</td><td>٥ كلمات، ٣ جمل، سؤالان</td></tr><tr><td>السكن والأثاث</td><td>أداة وجمع + وصف الغرفة</td><td>وصف من ٤–٦ جمل</td></tr><tr><td>الروتين والساعة</td><td>أفعال منفصلة + أمثلة الساعة</td><td>روتين بصوتك لمدة دقيقة</td></tr><tr><td>الأكل والهوايات والطقس</td><td>جملة وسؤال ورد طبيعي</td><td>حوار قصير من ٤ أدوار</td></tr><tr><td>القواعد والنطق</td><td>شرح + اختبار + تكرار صوتي</td><td>تصحيح خطأ واحد وإعادة استخدامه</td></tr></table></div><p class="subtle">المحتوى داخل خطوة أمثلة أصلية للتدريب؛ ليس منتجًا معتمدًا أو تابعًا لـGoethe أو DW أو Klett، ولا يعيد نشر الكتاب أو الصوتيات.</p></div><div class="source-grid" style="margin-top:20px">${SOURCE_LINKS.map(([name,levels,desc,url])=>`<article class="panel"><span class="badge">${levels}</span><h3>${name}</h3><p>${desc}</p><a href="${url}" target="_blank" rel="noopener">افتح المصدر الأصلي ↗</a></article>`).join('')}</div><div class="panel" style="margin-top:20px"><h3>ما الذي يعمل الآن، وما حدوده؟</h3><p class="word-notes">البحث والاختبارات والتصريفات والمراجعة والدفتر تعمل محليًا. الصوت يحتاج صوتًا ألمانيًا مثبتًا، والميكروفون يحتاج متصفحًا داعمًا وإذنًا. تصحيح الجمل مرجعي، وتقييم النطق ذاتي. لا مزامنة بين الأجهزة ولا ترجمة حية ولا ذكاء اصطناعي داخل النسخة الحالية.</p><p class="word-notes">Local Server يجعل التشغيل على جهازك من عنوان ثابت أكثر انتظامًا. Cloud يتيح الوصول من أجهزة أخرى، لكن لا يضيف وحده مزامنة أو تقييمًا ذكيًا؛ كل ميزة تحتاج تنفيذًا خاصًا. صدّر النسخة الكاملة من سجل التقدم عند الانتقال بين العناوين أو الأجهزة.</p></div>`;}
// Avoid treating punctuation or letter case as a grammar correction in free writing.
// Keep the original v1 state key and export route so old progress remains available.
const sourcesBeforeInventory=sources;
sources=function(){sourcesBeforeInventory();const inventory=document.createElement('section');inventory.className='panel';inventory.style.marginTop='20px';inventory.innerHTML='<h3>سجل مراجعة ملفات المشروع</h3><div class="table-wrap"><table class="data-table"><tr><th>المرجع</th><th>ما أمكن قراءته</th><th>الاستفادة هنا</th></tr><tr><td>1 Guten Tag</td><td>النص المتاح كاملًا</td><td>التعارف والضمائر والرسمي والعادي</td></tr><tr><td>Freunde, Kollegen und ich</td><td>النص المتاح كاملًا</td><td>المهن والأعداد والعمر</td></tr><tr><td>Nominativ / Akkusativ / Dativ</td><td>أول صفحتين</td><td>تدقيق الحالات وتصحيح التعميمات</td></tr><tr><td>Netzwerk Neu A1 — Kursbuch وÜbungsbuch</td><td>محاولة قراءة صفحات البداية؛ النص ممسوح</td><td>مرجع كتابي مع روابط Klett؛ لا مطابقة صفحة بصفحة</td></tr><tr><td>PHONETIK، das ist meine Mutter، der Tisch ist schön، 10.pdf</td><td>لم يتوفر نص مقروء</td><td>لم تُنسب إليها تفاصيل لم نقرأها</td></tr></table></div><p class="notice">تصحيح إضافي من مذكرة Guten Tag: مع er نقول <span class="inline-de">er möchte</span>، أما <span class="inline-de">ihr möchtet</span> فهي مع أنتم. أُضيف درس مستقل للطلب المهذب.</p>';$('#app').append(inventory);};
EXTRA_VIEWS.sources=sources;
if('speechSynthesis'in window)speechSynthesis.getVoices();
const requested=location.hash.slice(1);if(EXTRA_VIEWS[requested])view=requested;render();
